import {resumeHeading} from './resume-header.mjs?v=113';
// Conservative deterministic gate for source-backed accomplishment paragraphs and bullets.
const groups=[['built','developed','created'],['analyzed','analysed','examined'],['improved','enhanced'],['used','utilized']];
const stop=new Set('a an the and or to of for with using by on in through'.split(' '));
const terms=s=>String(s).toLowerCase().match(/[a-z0-9+#]+(?:[.-][a-z0-9]+)*/g)||[];
function canonical(word){return groups.findIndex(g=>g.includes(word))<0?word:'synonym-'+groups.findIndex(g=>g.includes(word));}
const marker=/^(\s*(?:[-*•●▪◦‣–—]|\d{1,2}[.)])\s*)(?=[\p{L}])/u;
const action=/^(?:I\s+)?(?:built|developed|created|implemented|designed|led|managed|delivered|automated|optimized|optimised|resolved|supported|collaborated|worked|maintained|integrated|improved|enhanced|reduced|increased|migrated|tested|deployed|documented|established|trained|processed|reconciled|validated|streamlined|provided|assisted|helped|contributed|leveraged|utilized|utilised|used|developing|building|designing|working)\b/i;
const contact=/(?:[\w.+-]+@[\w.-]+\.[a-z]{2,}|https?:\/\/|linkedin\.com)/i;
const qualification=/^(?:bachelor|master|doctor|ph\.?d|b\.?tech|m\.?tech|b\.?sc|m\.?sc|degree|certification|certified)\b/i;
function onset(line){return String(line).replace(marker,'').trim();}
function editable(line){return marker.test(line)||action.test(String(line).trim());}
export function safeLocalWording(before,after){if(!editable(before)||typeof after!=='string'||/[\r\n]/.test(after)||after.length>before.length*1.35||after.length<before.length*.65||after.trim()===before.trim())return false;if((before.match(marker)?.[0].trim()||'')!==(after.match(marker)?.[0].trim()||''))return false;const urls=s=>s.match(/https?:\/\/[^\s]+|[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi)||[];if(JSON.stringify(urls(before))!==JSON.stringify(urls(after)))return false;const a=terms(before),b=terms(after);const quantities=s=>s.match(/\b\d+(?:[.,]\d+)*%?\b/g)||[];if(JSON.stringify(quantities(before))!==JSON.stringify(quantities(after)))return false;const protectedWords=/\b(?:not|no|never|basic|beginner|intermediate|advanced|expert|familiar|assisted|helped|supported|contributed|led|owned|managed)\b/gi;if(JSON.stringify((before.match(protectedWords)||[]).map(s=>s.toLowerCase()))!==JSON.stringify((after.match(protectedWords)||[]).map(s=>s.toLowerCase())))return false;const content=s=>s.filter(w=>!stop.has(w)).map(canonical).sort();return JSON.stringify(content(a))===JSON.stringify(content(b));}
export function supportedWordingVariants(before){const m=before.match(/^(\s*(?:(?:[-*•●▪◦‣–—]|\d{1,2}[.)])\s*)?)(built|developed|created|analyzed|analysed|examined|improved|enhanced|used|utilized)\b/i);if(!m)return [];const group=groups.find(g=>g.includes(m[2].toLowerCase()))||[];return group.filter(w=>w!==m[2].toLowerCase()).map(w=>m[1]+(m[2][0]===m[2][0].toUpperCase()?w[0].toUpperCase()+w.slice(1):w)+before.slice(m[0].length).replace(/\r?\n\s*/g,' ')).filter(after=>safeLocalWording(before,after));}
export function bulletChoices(text){
 const lines=String(text||'').split('\n'),choices=[];let blocked=false;
 const heading=s=>resumeHeading.test(s)||/^(?:employment|career history|professional background|selected projects|key projects)\s*:?$/i.test(s);
 const work=s=>/experience|employment|career history|professional background|projects/i.test(s);
 const boundary=s=>heading(s)||contact.test(s)||qualification.test(s)||/^(?:(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s*)?(?:19|20)\d{2}\b/i.test(s)||/\b(?:present|current)\s*$/i.test(s)||/^(?:[A-Z][\w.+-]*\s*){1,6}$/.test(s);
 for(let i=0;i<lines.length;i++){
  const value=lines[i].trim(),body=onset(value);if(heading(value)){blocked=!work(value);continue;}
  if(blocked||!value||(contact.test(value)&&!action.test(body))||qualification.test(body)||!editable(value)||body.length<8||/\|.*(?:19|20)\d{2}|(?:19|20)\d{2}.*\|/.test(body)||/^(?:[A-Z][\w.-]*\s+){1,7}(?:Ltd|Limited|Inc|Corp|LLC)\.?$/.test(body)||(!action.test(body)&&boundary(body)))continue;
  let endIndex=i;
  while(endIndex+1<lines.length){const next=lines[endIndex+1],trim=next.trim();if(!trim||marker.test(next)||action.test(trim)||boundary(trim)||/^[A-Z][a-z]+(?: [A-Z][a-z]+){0,4}\s*\|/.test(trim))break;
   if(/^\s{2,}/.test(next)||/^[a-z(]/.test(trim)||!/[.!?:]$/.test(lines[endIndex].trim()))endIndex++;else break;
  }
  const line=lines.slice(i,endIndex+1).join('\n');if(line.length<=2000)choices.push({line,index:i,endIndex});i=endIndex;
 }return choices;
}

export function setupLocalTailoring(dialog,{getSource,getDraft,setDraft,getDescription}){
 const section=document.createElement('section');section.className='local-ai';section.innerHTML='<h3>Optional AI on this device</h3><p>Download a local model to suggest wording for an existing accomplishment. Requires WebGPU and around 1 GB of available GPU memory; downloads can be large. Model files come from public CDNs and Hugging Face. Resume text stays on this device. No API key or paid fallback.</p><button type="button" class="secondary" data-load>Enable local AI</button> <button type="button" class="secondary" data-stop disabled>Stop / unload</button><label>Accomplishment to improve<select data-bullet aria-describedby="accomplishment-options-status"></select></label><p id="accomplishment-options-status" data-choice-status role="status"></p><button type="button" class="secondary" data-generate disabled>Suggest role-specific wording</button><p role="status" data-ai-status></p><div data-suggestion></div>';
 dialog.querySelector('[data-draft]').closest('label').before(section);const q=s=>section.querySelector(s);let worker=null,ready=false,busy=false,sequence=0,active=null,rows=[];
 function refresh(){const select=q('[data-bullet]'),selected=select.value;rows=bulletChoices(getDraft());select.replaceChildren();select.disabled=!rows.length;for(const row of rows){const o=document.createElement('option');o.value=row.index;o.textContent=row.line.replace(/\s+/g,' ').slice(0,160);select.append(o);}if(rows.some(r=>String(r.index)===selected))select.value=selected;
 if(!rows.length){const o=document.createElement('option');o.value='';o.textContent='No accomplishments found yet';select.append(o);}q('[data-choice-status]').textContent=rows.length?rows.length+' accomplishment'+(rows.length===1?'':'s')+' available. Choose one to improve.':getDraft().trim()?'No experience or project accomplishments were found. Check the extracted text, or paste the missing descriptions into the draft below.':'Upload your resume on NextRole, or paste its text into the draft below, to populate this list.';
 q('[data-suggestion]').replaceChildren();q('[data-generate]').disabled=!ready||!rows.length||busy;}
 q('[data-bullet]').onchange=()=>{sequence++;q('[data-suggestion]').replaceChildren();q('[data-ai-status]').textContent='Selection changed. Request wording for the selected accomplishment.';};

 section.refresh=refresh;dialog.addEventListener('local-draft-changed',()=>{sequence++;refresh();});
 function stop(){sequence++;worker?.terminate();worker=null;ready=false;busy=false;active=null;q('[data-load]').disabled=false;q('[data-stop]').disabled=true;q('[data-generate]').disabled=true;q('[data-ai-status]').textContent='Local AI unloaded. Your draft is unchanged.';q('[data-suggestion]').replaceChildren();}
 q('[data-stop]').onclick=stop;
 q('[data-load]').onclick=()=>{if(!getDraft().trim()){q('[data-ai-status]').textContent='Upload or paste your resume before enabling local AI.';return;}if(!navigator.gpu){q('[data-ai-status]').textContent='This browser has no WebGPU support. Formatting and downloads remain available.';return;}q('[data-load]').disabled=true;q('[data-stop]').disabled=false;q('[data-ai-status]').textContent='Downloading the local model…';worker=new Worker(new URL('./local-ai-worker.mjs?v=122',import.meta.url),{type:'module'});worker.onerror=()=>{stop();q('[data-ai-status]').textContent='The local AI could not run on this device. No paid service was used.';};worker.onmessage=({data})=>{if(data.progress){q('[data-ai-status]').textContent=data.progress;return;}if(data.ready){ready=true;q('[data-ai-status]').textContent='Local AI ready. Select an accomplishment and paste the job description.';refresh();return;}if(data.error&&!active){stop();q('[data-ai-status]').textContent='The model could not load on this device. Check WebGPU support and model-download access; formatting remains available.';return;}if(!active||data.id!==active.id)return;busy=false;q('[data-generate]').disabled=false;if(data.error){q('[data-ai-status]').textContent='No safe suggestion was produced. Your draft is unchanged.';return;}const {snapshot,source,description,before,index,endIndex,id}=active;if(id!==sequence||snapshot!==getDraft()||source!==getSource()||description!==getDescription())return;const after=data.after;if(!data.checked||!safeLocalWording(before,after)){q('[data-ai-status]').textContent='No wording change passed the checks. Your draft is unchanged.';return;}const host=q('[data-suggestion]');host.replaceChildren();const old=document.createElement('p'),next=document.createElement('p'),confirm=document.createElement('label'),check=document.createElement('input'),apply=document.createElement('button');old.textContent='Before: '+before;next.textContent=(data.variant?'Supported wording option: ':'Suggestion: ')+after;check.type='checkbox';confirm.append(check,document.createTextNode(' I checked that the meaning and facts are unchanged.'));apply.type='button';apply.className='secondary';apply.textContent='Apply this wording';apply.disabled=true;check.onchange=()=>apply.disabled=!check.checked;apply.onclick=()=>{if(snapshot!==getDraft()||source!==getSource()||description!==getDescription()){q('[data-ai-status]').textContent='The resume or job changed. Request a fresh suggestion.';return;}const lines=snapshot.split('\n');if(lines.slice(index,endIndex+1).join('\n')!==before)return;lines.splice(index,endIndex-index+1,after);setDraft(lines.join('\n'));q('[data-ai-status]').textContent='Approved wording applied to the download draft only.';refresh();};host.append(old,next,confirm,apply);q('[data-ai-status]').textContent='Review the suggestion. Names, numbers, proficiency and content words are protected.';};worker.postMessage({type:'load'});};
 q('[data-generate]').onclick=()=>{const row=rows.find(r=>String(r.index)===q('[data-bullet]').value),description=getDescription();if(!row||description.trim().length<40){q('[data-ai-status]').textContent='Paste the job description and select an existing accomplishment first.';return;}busy=true;q('[data-generate]').disabled=true;q('[data-suggestion]').replaceChildren();const id=++sequence;active={id,index:row.index,endIndex:row.endIndex,before:row.line,source:getSource(),snapshot:getDraft(),description};q('[data-ai-status]').textContent='Reviewing the selected wording locally…';worker.postMessage({type:'suggest',id,before:row.line,description:description.slice(0,1500)});};refresh();return {refresh,stop};
}
